/// Memory / instruction files contributing to the system prompt
/// hierarchy — one list, shared by `memory_files` and
/// `system_prompt.memory_files`.
const PI_MEMORY_FILES: &[PathTemplate] = &[
    PathTemplate::Static("~/.pi/agent/AGENTS.md"),
    PathTemplate::Static("~/.pi/agent/CLAUDE.md"),
    PathTemplate::Static("AGENTS.md"),
    PathTemplate::Static("CLAUDE.md"),
];

/// Builds the resource portability descriptor served through
/// `resource_support_fn` (heap-backed, so it lives behind the `LazyLock`
/// rather than in the `ProviderInfo` static).
fn build_resource_support() -> ProviderCapabilities {
    ProviderCapabilities {
        provider: Provider::Pi,
        skills: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".pi/skills")),
            user_path: Some(PathBuf::from(".pi/agent/skills")),
            also_reads_from: vec![PathBuf::from(".agents/skills")],
            notes: Some("Agent Skills standard; Pi does not enforce name == directory name and also accepts Pi-native direct root *.md skills."),
            properties: Some(ResourcePropertySchema::new(
                &["name", "description"],
                &["license", "compatibility", "metadata"],
                "claudine/docs/research/skills/pi.md",
            )),
        },
        commands: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".pi/prompts")),
            user_path: Some(PathBuf::from(".pi/agent/prompts")),
            also_reads_from: vec![],
            notes: Some("Prompt templates; the filename (minus .md) becomes the /command name. Shell-style $1/$@/$ARGUMENTS substitution."),
            properties: Some(ResourcePropertySchema::new(
                &[],
                &["description", "argument-hint"],
                "claudine/docs/research/slash-commands/pi.md",
            )),
        },
        agents: ResourceSupport {
            level: SupportLevel::None,
            format: None,
            repo_path: None,
            user_path: None,
            also_reads_from: vec![],
            notes: Some("No native subagents; the optional example `subagent` extension reads ~/.pi/agent/agents/*.md and .pi/agents/*.md but is not in the default install."),
            properties: None,
        },
        scripts: ResourceSupport {
            level: SupportLevel::None,
            format: None,
            repo_path: None,
            user_path: None,
            also_reads_from: vec![],
            notes: Some("Scripts are stored within skill directories (freeform sibling files resolved relative to the skill dir); Pi has no dedicated scripts resource directory."),
            properties: None,
        },
        skill_frontmatter: SkillFrontmatter {
            name: true,
            description: true,
            license: true,
            compatibility: true,
            metadata: true,
            allowed_tools: true,
            user_invocable: false,
            disable_model_invocation: true,
        },
    }
}
